WITH filtered AS (SELECT id, order_id, product_id, unit_price, CASE WHEN quantity >= 7 THEN 'High' WHEN quantity >= 2 THEN 'Medium' ELSE 'Low' END AS quantity_tier FROM order_items WHERE product_id IS NOT NULL), with_dims AS (SELECT s.*, b.amount, b.discount, b.channel FROM filtered s LEFT JOIN orders b ON s.order_id = b.id), ranked AS (SELECT * FROM with_dims QUALIFY RANK() OVER (PARTITION BY channel ORDER BY unit_price) = 1), cleaned AS (SELECT *, ROUND(unit_price, 0) AS unit_price_rounded, COALESCE(channel, 'NONE') AS resolved_channel FROM ranked WHERE product_id IN (13, 39)), ranked_order_items AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel, product_id ORDER BY amount NULLS FIRST, id) AS latest_rank FROM cleaned QUALIFY latest_rank = 1), scored AS (SELECT id, order_id, product_id, unit_price, quantity_tier, amount, discount, channel, unit_price_rounded, resolved_channel, latest_rank, SUM(discount) OVER (PARTITION BY product_id ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_discount, SUM(discount) OVER (PARTITION BY order_id ORDER BY latest_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_discount_2 FROM ranked_order_items) SELECT * FROM (SELECT id, product_id, discount, unit_price, amount, unit_price_rounded FROM scored) src UNPIVOT (val FOR metric IN (discount, unit_price, amount, unit_price_rounded))
